window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-157b1d185c97b89b"]={"versions": [{"id": "FIG-157b1d185c97b89b", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm im Kontext des AUTOSAR-Metamodells (Interoperability of AUTOSAR Tools). Das Diagramm illustriert das Granularitätskonzept bei der Erkennung von Modelländerungen (Modification Detection) bei Kompositions- und Aggregationshierarchien nicht-identifizierbarer Metaklassen unterhalb eines identifizierbaren Elements.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Metaklassen und deren strukturelle Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>A</code>: Spezialisierung bzw. Ausprägung der Metaklasse <code>Identifiable</code> (gekennzeichnet durch die kursive Annotation <em>Identifiable</em> und hervorgehoben durch gelb-orange Hintergrundfärbung). Die Klasse besitzt ein abgetrenntes, leeres Attributfach.\n</li><li><code>B</code>: Nicht-identifizierbare Metaklasse, hell hinterlegt, mit abgetrenntem unterem Kompartiment. Sie steht in einer Kompositionsbeziehung (gefüllte Raute) zu <code>A</code> (<code>A</code> aggregiert <code>B</code>).\n</li><li><code>B1</code>: Nicht-identifizierbare Metaklasse, hell hinterlegt, mit abgetrenntem unterem Kompartiment. Sie steht in einer Kompositionsbeziehung (gefüllte Raute) zu <code>B</code> (<code>B</code> aggregiert <code>B1</code>).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen oder explizite Rollennamen und Multiplizitäten sind an den Aggregationskanten nicht ausgewiesen.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Verhaltens- oder Sequenzpfade. Die farbliche Markierung von <code>A</code> repräsentiert das Ergebnis einer Modifikationserkennung: Änderungen in verschachtelten, nicht-identifizierbaren Unterstrukturen (<code>B</code> oder <code>B1</code>) propagieren rekursiv auf das übergeordnete <code>Identifiable</code> (<code>A</code>), welches dadurch als geändert markiert wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Werkzeugentwickler (Differenzierungs-, Merge- und Vergleichswerkzeuge) definiert das Diagramm die minimale Granularität der Änderungserkennung: Da nur Spezialisierungen von <code>Identifiable</code> über eine eigene Identität verfügen, führen Wert- oder Strukturänderungen an aggregierten, nicht-identifizierbaren Elementen (<code>B</code>, <code>B1</code>) zur Kennzeichnung des umschließenden <code>Identifiable</code> (<code>A</code>) als modifiziert. Werkzeuge müssen rekursiv aggregierte Kindelemente in die Modifikationserkennung der Identifiables einbeziehen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d303d649bcc8b625", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm im Kontext des AUTOSAR-Metamodells (Interoperability of AUTOSAR Tools). Das Diagramm illustriert das Granularitätskonzept bei der Erkennung von Modelländerungen (Modification Detection) bei Kompositions- und Aggregationshierarchien nicht-identifizierbarer Metaklassen unterhalb eines identifizierbaren Elements.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert drei Metaklassen und deren strukturelle Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>A</code>: Spezialisierung bzw. Ausprägung der Metaklasse <code>Identifiable</code> (gekennzeichnet durch die kursive Annotation <em>Identifiable</em> und hervorgehoben durch gelb-orange Hintergrundfärbung), dargestellt als einzelner ungeteilter Klassenkasten.\n</li><li><code>B</code>: Nicht-identifizierbare Metaklasse, hell hinterlegt, dargestellt als einzelner ungeteilter Klassenkasten. Sie steht in einer Kompositionsbeziehung (gefüllte Raute) zu <code>A</code> (<code>A</code> aggregiert <code>B</code>).\n</li><li><code>B1</code>: Nicht-identifizierbare Metaklasse, hell hinterlegt, dargestellt als einzelner ungeteilter Klassenkasten. Sie steht in einer Kompositionsbeziehung (gefüllte Raute) zu <code>B</code> (<code>B</code> aggregiert <code>B1</code>).\n</li></ul>\n<p class=\"fig-p\">Schnittstellen oder explizite Rollennamen und Multiplizitäten sind an den Aggregationskanten nicht ausgewiesen.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Verhaltens- oder Sequenzpfade. Die farbliche Markierung von <code>A</code> repräsentiert das Ergebnis einer Modifikationserkennung: Änderungen in verschachtelten, nicht-identifizierbaren Unterstrukturen (<code>B</code> oder <code>B1</code>) propagieren rekursiv auf das übergeordnete <code>Identifiable</code> (<code>A</code>), welches dadurch als geändert markiert wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Werkzeugentwickler (Differenzierungs-, Merge- und Vergleichswerkzeuge) definiert das Diagramm die minimale Granularität der Änderungserkennung: Da nur Spezialisierungen von <code>Identifiable</code> über eine eigene Identität verfügen, führen Wert- oder Strukturänderungen an aggregierten, nicht-identifizierbaren Elementen (<code>B</code>, <code>B1</code>) zur Kennzeichnung des umschließenden <code>Identifiable</code> (<code>A</code>) als modifiziert. Werkzeuge müssen rekursiv aggregierte Kindelemente in die Modifikationserkennung der Identifiables einbeziehen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-157b1d185c97b89b", "to": "FIG-d303d649bcc8b625", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Layout: Die horizontalen Trennlinien zur Abtrennung der unteren Klassen-Kompartimente (für Attribute/Operationen) innerhalb der Klassenkästen <code>A</code>, <code>B</code> und <code>B1</code> wurden entfernt.\n</li></ul>"}]};
